<original_code>
#include <cstdio>
#include <algorithm>
#include <vector>
#include <stack>

using namespace std;

int readInt()
{
    int x;
    scanf("%d",&x);
    return x;
}

bool visited_nodes[1000007];
const int MOD_CONST=1000000007;
long long count_divisors[1000007];
long long cycle_lengths_arr[1000007];
long long dp_vals[1000007];

int main()
{
    long long answer=1;
    int p, k;
    p=readInt();
    k=readInt();
    for(int i=0; i<p; i++)
    {
        if(!visited_nodes[i])
        {
            int length=0;
            long long current=i;
            while(!visited_nodes[current])
            {
                visited_nodes[current]=1;
                current=((long long)k*current)%p;
                length++;
            }
            cycle_lengths_arr[length]++;
        }
    }
    for(int i=1; i<=p; i++)
    {
        dp_vals[i]=((long long)cycle_lengths_arr[i]*i)%MOD_CONST;
    }
    for(int i=1; i<=p; i++)
    {
        count_divisors[i]=(count_divisors[i]+dp_vals[i])%MOD_CONST;
        for(int j=i+i; j<=p; j+=i)
        {
            count_divisors[j]=(dp_vals[i]+count_divisors[j])%MOD_CONST;
        }
    }
    for(int i=1; i<=p; i++)
    {
        if(i==1)
        {
            for(int j=0; j<cycle_lengths_arr[i]-1; j++)
                answer=(answer*(long long)cycle_lengths_arr[i])%MOD_CONST;
        }
        else
        {
            for(int j=0; j<cycle_lengths_arr[i]; j++)
                answer=(answer*(long long)count_divisors[i])%MOD_CONST;
        }
    }
    if(k==1) answer=(answer*count_divisors[1])%MOD_CONST;
    printf("%lld", answer);
    return 0;
}
